"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["51839"],{83637(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.termo_versao_nao_encontrada","status":422,"titulo":"A vers\xe3o do termo n\xe3o existe no cat\xe1logo ou pertence a outro termo"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.termo_versao_nao_encontrada","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["Um termo de `termos`, no `conteudo` do modelo enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), traz um `versaoId` que n\xe3o existe no cat\xe1logo de termos de consentimento, ou que existe mas pertence a outro termo que n\xe3o o indicado em `termoId`. O termo \xe9 um campo do formul\xe1rio escolhido de um cat\xe1logo, nunca digitado como texto livre (UNI-REQ-0086), e o modelo guarda a vers\xe3o exata que escolheu.","A recusa vem na lista `errors` da resposta, com `field` igual a `conteudo.termos[i].versaoId`, em que `i` \xe9 a posi\xe7\xe3o do termo. Na atualiza\xe7\xe3o, s\xf3 o v\xednculo novo \xe9 conferido: a vers\xe3o que o modelo j\xe1 tinha escolhido continua valendo, mesmo que o termo tenha sido exclu\xeddo do cat\xe1logo depois. Na cria\xe7\xe3o, todos os termos s\xe3o v\xednculos novos. As demais recusas do conte\xfado v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Consulte o termo no cat\xe1logo (`GET /api/configuracao/termos-consentimento/{id}`) e use no `versaoId` uma vers\xe3o desse mesmo termo, informado em `termoId`. Se o termo ainda n\xe3o tem a vers\xe3o desejada, ela precisa ser cadastrada no cat\xe1logo antes."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);